CAT = "oacpPunct"; SEG = "PUN"
Q = [
("Which sentence from the occurrence report is punctuated correctly?", "When the officer arrived, the door was already open.", ["When the officer arrived the door, was already open.", "When, the officer arrived the door was already open.", "When the officer arrived; the door was already open."], "An introductory clause is followed by a comma before the main clause. A semicolon cannot follow a dependent clause like \"When the officer arrived.\""),
("In the sentence \"Bring these items to court___ your notebook, the report and the photos.\", which mark belongs in the blank?", "a colon", ["a semicolon", "a period", "no mark"], "A colon introduces a list after a complete clause. A semicolon would wrongly join a clause to a list that cannot stand alone."),
("Which sentence avoids a comma splice?", "The suspect ran north; two officers followed him.", ["The suspect ran north, two officers followed him.", "The suspect ran north two officers, followed him.", "The suspect ran, north; two officers followed him."], "Two complete sentences can be joined with a semicolon. Joining them with only a comma, as in \"ran north, two officers,\" is a comma splice."),
("Which sentence sets off the extra information about the constable correctly?", "Constable Patel, who was off duty, called 911.", ["Constable Patel who was off duty, called 911.", "Constable Patel, who was off duty called 911.", "Constable, Patel who was off duty, called 911."], "A non-restrictive clause needs a comma on both sides. Leaving out either comma, as in \"who was off duty called,\" breaks the pair."),
("Which sentence uses the possessive correctly?", "The children's bikes were taken from the garage.", ["The childrens' bikes were taken from the garage.", "The childrens bikes were taken from the garage.", "The children's' bikes were taken from the garage."], "Children is already plural, so its possessive adds 's: children's. Childrens' treats the plural as if it were childrens, which is not a word."),
("Which line of reported dialogue is punctuated correctly?", "\"Sir, please step out of the car,\" she said.", ["\"Sir please step out of the car,\" she said.", "\"Sir, please step out of the car\", she said.", "\"Sir, please step out of the car.\" she said."], "A name or title used in direct address is set off by a comma, and in Canadian usage the comma before \"she said\" goes inside the closing quotation mark. A period would end the sentence too soon."),
("Which sentence writes the full date correctly?", "On Friday, March 7, 2025, the store was robbed.", ["On Friday March 7, 2025 the store was robbed.", "On Friday, March, 7, 2025, the store was robbed.", "On Friday, March 7, 2025 the store was robbed."], "In a full date the day of the week, the day and the year are each set off by commas, including the comma after the year. Dropping that last comma is the most common slip."),
("In the sentence \"The officer who found the wallet___ returned it to the owner.\", which mark belongs in the blank?", "no mark", ["a comma", "a semicolon", "a colon"], "\"Who found the wallet\" identifies which officer, so it is restrictive and takes no comma. A single comma would wrongly split the subject from its verb."),
("Which sentence punctuates the address correctly?", "She lives at 40 King Street, Hamilton, Ontario.", ["She lives at 40 King Street Hamilton, Ontario.", "She lives at 40, King Street, Hamilton, Ontario.", "She lives at 40 King Street, Hamilton Ontario."], "Commas separate the street, the city and the province. No comma goes between the house number and the street name."),
("Which sentence uses \"however\" with the correct punctuation?", "The alarm sounded; however, no one left the building.", ["The alarm sounded, however, no one left the building.", "The alarm sounded; however no one left the building.", "The alarm sounded however; no one left the building."], "When \"however\" joins two complete sentences, it takes a semicolon before it and a comma after it. Commas on both sides create a comma splice."),
("Which sentence uses the colon correctly?", "The bag held three items: a phone, keys and a wallet.", ["The bag held: three items, a phone, keys and a wallet.", "The bag held three items; a phone, keys and a wallet.", "The bag held three: items a phone, keys and a wallet."], "A colon comes after a complete clause, \"The bag held three items,\" to introduce the list. A semicolon cannot introduce a list."),
("Which sentence lists the seized items without a punctuation error?", "The officers seized a knife, a bat and two phones.", ["The officers seized: a knife, a bat and two phones.", "The officers seized a knife: a bat and two phones.", "The officers seized; a knife, a bat and two phones."], "No colon belongs between a verb and its objects. \"The officers seized\" is not a complete clause, so a colon after it is wrong."),
("Which sentence shows that the bikes belong to several boys?", "The boys' bikes were left on the lawn.", ["The boy's bikes were left on the lawn.", "The boys bike's were left on the lawn.", "The boys's bikes were left on the lawn."], "For a plural noun ending in s, the apostrophe goes after the s: \"boys'.\" \"Boy's\" would mean the bikes belong to one boy."),
("Which sentence from the officer's notes is punctuated correctly?", "The suspect didn't stop at the red light.", ["The suspect did'nt stop at the red light.", "The suspect didnt' stop at the red light.", "The suspect didnt stop at the red light."], "In a contraction the apostrophe replaces the missing letter, here the o in \"not.\" \"Did'nt\" puts it in the wrong place."),
("Which sentence quotes the suspect correctly?", "He said, \"I was home all night.\"", ["He said, \"I was home all night\".", "He said, \"i was home all night.\"", "He said, \"I was home all night\""], "In Canadian usage the period always goes inside the closing quotation mark, and a quoted sentence starts with a capital."),
("In the sentence \"Although the lights were off___ the store was not empty.\", which mark belongs in the blank?", "a comma", ["a semicolon", "a colon", "a period"], "A comma follows an introductory clause that begins with \"although.\" A semicolon or a period would leave the clause cut off from the sentence it belongs to."),
("Which question from the witness interview is punctuated correctly?", "The clerk asked, \"Is anyone hurt?\"", ["The clerk asked, \"Is anyone hurt\"?", "The clerk asked, \"Is anyone hurt?\".", "The clerk asked, \"is anyone hurt?\""], "When the quoted words are a question, the question mark goes inside the quotation marks and no other end mark is added."),
("Which sentence reports what the victim said correctly?", "The victim said that she did not see the driver.", ["The victim said that, \"she did not see the driver.\"", "The victim said, that she did not see the driver.", "The victim said \"that she did not see the driver.\""], "This is indirect speech, introduced by \"that,\" so it needs no quotation marks and no comma. Quotation marks are only for the speaker's exact words."),
("Which sentence about the witnesses is punctuated correctly?", "Both witnesses gave statements at the scene.", ["Both witness's gave statements at the scene.", "Both witnesses' gave statements at the scene.", "Both witnesse's gave statements at the scene."], "\"Witnesses\" is a simple plural here, not a possessive, so it takes no apostrophe. An apostrophe is not used to make a word plural."),
("Which sentence uses capital letters correctly?", "Sergeant Ruiz briefed the constables at noon.", ["sergeant Ruiz briefed the constables at noon.", "Sergeant Ruiz briefed the Constables at noon.", "Sergeant ruiz briefed the constables at noon."], "A title directly before a name is capitalized, and so is the name. \"Constables\" used as a general job word stays lower case."),
("In the sentence \"The van was stolen on Tuesday___ it was found on Friday.\", which mark belongs in the blank?", "a semicolon", ["a comma", "an apostrophe", "a quotation mark"], "Two complete sentences joined without a conjunction need a semicolon. A comma alone would make a comma splice."),
("Which sentence about the meeting is capitalized correctly?", "The constable spoke with the mayor of Barrie.", ["The Constable spoke with the mayor of Barrie.", "The constable spoke with the mayor of barrie.", "the constable spoke with the mayor of Barrie."], "A title used without a name, \"the constable,\" stays lower case, but a city name like Barrie is always capitalized."),
("Which sentence capitalizes the time words correctly?", "The break-in happened on a Monday last winter.", ["The break-in happened on a monday last winter.", "The break-in happened on a Monday last Winter.", "The break-in happened on a monday last Winter."], "Days of the week and months are capitalized, but seasons such as winter are not."),
("Which version of the clause beginning with \"that\" is punctuated correctly?", "The car that hit the pole was a red sedan.", ["The car, that hit the pole, was a red sedan.", "The car that hit the pole, was a red sedan.", "The car, that hit the pole was a red sedan."], "A clause beginning with \"that\" identifies which car, so it is restrictive and takes no commas. A comma before \"was\" would separate the subject from its verb."),
("Which sentence names the location with the correct capitals?", "The crash was on Highway 401 near Kingston.", ["The crash was on highway 401 near Kingston.", "The crash was on Highway 401 near kingston.", "The crash was on Highway 401 Near Kingston."], "\"Highway 401\" is the name of a specific road and Kingston is a city, so both are capitalized. A word like \"near\" stays lower case."),
("Which sentence beginning with \"However\" is punctuated correctly?", "However, the witness could not describe the car.", ["However the witness, could not describe the car.", "However; the witness could not describe the car.", "However: the witness could not describe the car."], "\"However\" at the start of a sentence is followed by a comma. A semicolon or colon cannot follow a single word that is not a complete clause."),
("Which sentence joins the two clauses with the correct punctuation?", "The suspect was arrested, and his car was towed.", ["The suspect was arrested and, his car was towed.", "The suspect was arrested; and his car was towed.", "The suspect, was arrested and his car was towed."], "When \"and\" joins two complete clauses, the comma goes before \"and.\" A semicolon is not used together with \"and\" in a sentence like this."),
("Which sentence about the found car uses the apostrophe correctly?", "Mr. Chen's car was found behind the arena.", ["Mr. Chens' car was found behind the arena.", "Mr. Chens car was found behind the arena.", "Mr. Chen car's was found behind the arena."], "To show that one person owns something, add an apostrophe and s to the name: \"Chen's.\" \"Chens'\" would be the form for a plural name."),
]
